package chiawalletsdk_test

import (
	"bytes"
	"testing"

	sdk "github.com/xch-dev/chia-wallet-sdk/go/chiawalletsdk"
)

// Ported from the Clvm.alloc tests for the Go bindings in #370. There, alloc took Go values and
// converted them itself. Here it takes the ClvmType union generated by UniFFI.

func TestAllocProgramPairAndCurry(t *testing.T) {
	clvm := must(sdk.NewClvm())
	defer clvm.Destroy()

	one := must(clvm.Int("1"))
	two := must(clvm.Int("2"))

	program := must(clvm.Alloc(sdk.ClvmTypeProgram{Value: one}))
	if !bytes.Equal(must(program.TreeHash()), must(one.TreeHash())) {
		t.Fatal("expected allocating a program to return the same program")
	}

	pair := must(sdk.NewPair(one, two))
	defer pair.Destroy()

	allocatedPair := must(clvm.Alloc(sdk.ClvmTypePair{Value: pair}))
	if !bytes.Equal(must(allocatedPair.TreeHash()), must(must(clvm.Pair(one, two)).TreeHash())) {
		t.Fatal("expected the allocated pair to match Clvm.Pair")
	}

	curried := must(sdk.NewCurriedProgram(one, []*sdk.Program{two}))
	defer curried.Destroy()

	allocatedCurry := must(clvm.Alloc(sdk.ClvmTypeCurriedProgram{Value: curried}))
	if !bytes.Equal(must(allocatedCurry.TreeHash()), must(must(one.Curry([]*sdk.Program{two})).TreeHash())) {
		t.Fatal("expected the allocated curried program to match Program.Curry")
	}

	uncurried := must(allocatedCurry.Uncurry())
	if uncurried == nil || len((*uncurried).Args()) != 1 {
		t.Fatal("expected the curried program to uncurry with 1 argument")
	}
}

func TestAllocKeysAndSignatures(t *testing.T) {
	clvm := must(sdk.NewClvm())
	defer clvm.Destroy()

	sk := must(sdk.SecretKeyFromSeed(seed(0)))
	defer sk.Destroy()

	sig := must(sk.Sign([]byte("message")))
	defer sig.Destroy()

	for _, c := range []struct {
		value    sdk.ClvmType
		expected []byte
	}{
		{sdk.ClvmTypeSignature{Value: sig}, must(sig.ToBytes())},
	} {
		program := must(clvm.Alloc(c.value))
		if atom := must(program.ToAtom()); atom == nil || !bytes.Equal(*atom, c.expected) {
			t.Fatalf("expected %T to allocate its bytes", c.value)
		}
		program.Destroy()
	}
}

func TestAllocConditions(t *testing.T) {
	clvm := must(sdk.NewClvm())
	defer clvm.Destroy()

	puzzleHash := seed(0xab)

	createCoin := must(sdk.NewCreateCoin(puzzleHash, 999, nil))
	defer createCoin.Destroy()

	reserveFee := must(sdk.NewReserveFee(500))
	defer reserveFee.Destroy()

	assertEphemeral := must(sdk.NewAssertEphemeral())
	defer assertEphemeral.Destroy()

	meltSingleton := must(sdk.NewMeltSingleton())
	defer meltSingleton.Destroy()

	cases := []struct {
		value    sdk.ClvmType
		expected *sdk.Program
	}{
		{sdk.ClvmTypeCreateCoin{Value: createCoin}, must(clvm.CreateCoin(puzzleHash, 999, nil))},
		{sdk.ClvmTypeReserveFee{Value: reserveFee}, must(clvm.ReserveFee(500))},
		{sdk.ClvmTypeAssertEphemeral{Value: assertEphemeral}, must(clvm.AssertEphemeral())},
	}

	for _, c := range cases {
		program := must(clvm.Alloc(c.value))
		if !bytes.Equal(must(program.TreeHash()), must(c.expected.TreeHash())) {
			t.Errorf("expected %T to match the condition built by Clvm", c.value)
		}

		// The condition survives serialization
		roundtrip := must(clvm.Deserialize(must(program.Serialize())))
		if !bytes.Equal(must(roundtrip.TreeHash()), must(c.expected.TreeHash())) {
			t.Errorf("expected %T to roundtrip through serialization", c.value)
		}
	}

	if parsed := must(must(clvm.Alloc(sdk.ClvmTypeCreateCoin{Value: createCoin})).ParseCreateCoin()); parsed == nil || (*parsed).Amount() != 999 {
		t.Fatal("expected the create coin condition to parse back")
	}

	if parsed := must(must(clvm.Alloc(sdk.ClvmTypeReserveFee{Value: reserveFee})).ParseReserveFee()); parsed == nil || (*parsed).Amount() != 500 {
		t.Fatal("expected the reserve fee condition to parse back")
	}

	if parsed := must(must(clvm.Alloc(sdk.ClvmTypeMeltSingleton{Value: meltSingleton})).ParseMeltSingleton()); parsed == nil {
		t.Fatal("expected the melt singleton condition to parse back")
	}
}

func TestAllocPayments(t *testing.T) {
	clvm := must(sdk.NewClvm())
	defer clvm.Destroy()

	memos := must(clvm.List([]*sdk.Program{must(clvm.Atom(seed(0xab)))}))

	payment := must(sdk.NewPayment(seed(0xab), 500, &memos))
	defer payment.Destroy()

	program := must(clvm.Alloc(sdk.ClvmTypePayment{Value: payment}))

	parsed := must(program.ParsePayment())
	if parsed == nil || (*parsed).Amount() != 500 || !bytes.Equal((*parsed).PuzzleHash(), seed(0xab)) {
		t.Fatal("expected the payment to parse back")
	}

	if parsedMemos := (*parsed).Memos(); parsedMemos == nil || !bytes.Equal(must((*parsedMemos).TreeHash()), must(memos.TreeHash())) {
		t.Fatal("expected the payment memos to roundtrip")
	}

	notarized := must(sdk.NewNotarizedPayment(seed(1), []*sdk.Payment{payment}))
	defer notarized.Destroy()

	parsedNotarized := must(must(clvm.Alloc(sdk.ClvmTypeNotarizedPayment{Value: notarized})).ParseNotarizedPayment())
	if parsedNotarized == nil || !bytes.Equal((*parsedNotarized).Nonce(), seed(1)) || len((*parsedNotarized).Payments()) != 1 {
		t.Fatal("expected the notarized payment to parse back")
	}
}

func TestAllocMetadata(t *testing.T) {
	clvm := must(sdk.NewClvm())
	defer clvm.Destroy()

	strikeType := must(sdk.OptionTypeNewXch(1000))
	defer strikeType.Destroy()

	optionMetadata := must(sdk.NewOptionMetadata(3600, strikeType))
	defer optionMetadata.Destroy()

	parsedOption := must(must(clvm.Alloc(sdk.ClvmTypeOptionMetadata{Value: optionMetadata})).ParseOptionMetadata())
	if parsedOption == nil || (*parsedOption).ExpirationSeconds() != 3600 {
		t.Fatal("expected the option metadata to parse back")
	}

	name := "example"
	handleMetadata := must(sdk.NewHandleNftMetadata(&name, nil, nil, nil, nil, nil, nil))
	defer handleMetadata.Destroy()

	parsedHandle := must(must(clvm.Alloc(sdk.ClvmTypeHandleNftMetadata{Value: handleMetadata})).ParseHandleNftMetadata())
	if parsedHandle == nil {
		t.Fatal("expected the handle metadata to parse back")
	}

	if displayName := (*parsedHandle).DisplayName(); displayName == nil || *displayName != name {
		t.Fatalf("expected the display name %q, got %v", name, deref(displayName))
	}

	nftMetadata := must(sdk.NewNftMetadata(1, 10, []string{"https://example.com"}, nil, nil, nil, nil, nil))
	defer nftMetadata.Destroy()

	allocated := must(clvm.Alloc(sdk.ClvmTypeNftMetadata{Value: nftMetadata}))
	if !bytes.Equal(must(allocated.TreeHash()), must(must(clvm.NftMetadata(nftMetadata)).TreeHash())) {
		t.Fatal("expected the allocated NFT metadata to match Clvm.NftMetadata")
	}
}
